<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Game extends Model { protected $casts=['name'=>'array','rules'=>'array','partnership'=>'bool']; protected $fillable=['key','name','min_players','max_players','partnership','rules','active']; public function competitiveRatings(){return $this->hasMany(CompetitiveRating::class);} public function competitiveMatches(){return $this->hasMany(CompetitiveMatch::class);} }
